'use strict';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',stack:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 5 9 4 9-4M3 17l9 4 9-4"/>',scan:'<path d="M8 3H4a1 1 0 0 0-1 1v4m13-5h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m8 0h4a1 1 0 0 0 1-1v-4M8 12h8m-4-4v8"/>',flow:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/><path d="M6 9v9h9M9 6h9v9"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8v-5"/>',building:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 7h1m4 0h1m-6 4h1m4 0h1m-5 10v-6h4v6"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',bell:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4l-2 4Zm5 3h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',filter:'<path d="M3 6h18M6 12h12m-8 6h4"/>',sort:'<path d="M8 4v16m-4-4 4 4 4-4M16 4v16m-4-12 4-4 4 4"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8V5l14-2v2m-1 7h5v5h-5a2.5 2.5 0 0 1 0-5Z"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const $=selector=>document.querySelector(selector);
document.querySelectorAll('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon));
const rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const compact=n=>`${(n/(n>=1e9?1e9:1e6)).toLocaleString('id-ID',{maximumFractionDigits:1})} ${n>=1e9?'M':'jt'}`;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let claims=[];
const state={view:'overview',status:'all',risk:'all',search:'',period:30,page:1,descending:true};
const labels={APPROVED:'Disetujui',HOLD:'Perlu review',REJECTED:'Ditolak',PENDING:'Menunggu review'};
const levels=c=>c.score>=70?'high':c.score>=35?'medium':'low';
const tag=c=>`<span class="tag ${c.status==='HOLD'?'hold':c.status==='REJECTED'?'rejected':c.status==='PENDING'?'neutral':''}">${labels[c.status]}</span>`;
let summaryCache=null,tableRequest=0,summaryRequest=0;
const query=()=>new URLSearchParams({period:state.period,status:state.status,risk:state.risk,search:state.search,view:state.view,page:state.page,limit:6,sort:state.descending?'desc':'asc'});
async function apiJSON(url,options){const response=await fetch(url,{cache:'no-store',...options});if(!response.headers.get('content-type')?.includes('application/json'))throw Error('Layanan sementara belum tersedia.');const body=await response.json();if(!response.ok)throw Error(body.error||'Permintaan belum berhasil.');return body;}
async function renderMetrics(){const request=++summaryRequest;try{const data=await apiJSON('/api/claims/summary?period='+state.period);if(request!==summaryRequest)return;summaryCache=data;const {count,amount,hold,high,exposure}=data;$('#queue-count').textContent=hold;const metrics=[['Total nilai klaim',`Rp ${compact(amount)}`,`${count.toLocaleString('id-ID')} klaim dalam periode ini`,'wallet',false],['Perlu ditinjau',hold.toLocaleString('id-ID'),`<b>${Math.round(hold/Math.max(1,count)*100)}%</b> dari seluruh klaim`,'stack',false],['Sinyal risiko tinggi',high.toLocaleString('id-ID'),'Prioritas aturan + ML 70 atau lebih','scan',false],['Selisih perlu diperiksa',`Rp ${compact(exposure)}`,'Di atas tarif · klaim risiko tinggi','shield',true]];$('#metrics').innerHTML=metrics.map(([label,value,sub,glyph,dark])=>`<article class="metric ${dark?'featured':''}"><div class="metric-head"><span>${label}</span>${icon(glyph)}</div><strong class="metric-value">${value}</strong><span class="metric-sub">${sub}</span></article>`).join('');renderCharts(data);}catch(error){notify(error.message);}}
function renderCharts(data){$('#chart-total').textContent=data.count.toLocaleString('id-ID');const anchor=Date.parse(data.metadata.anchorDate+'T12:00:00Z'),dayLabel=days=>new Date(anchor-days*86400000).toLocaleDateString('id-ID',{day:'numeric',month:'short',timeZone:'UTC'});$('#chart-range').textContent=dayLabel(state.period-1)+'–'+dayLabel(0)+' '+data.metadata.anchorDate.slice(0,4);const buckets=data.buckets;const max=Math.max(...buckets.map(b=>b.all),10);$('#bar-chart').innerHTML=buckets.map((b,i)=>`<div class="bar-column" title="${b.all} klaim; ${b.reviewed} sudah ditinjau"><div class="bar" style="--height:${b.all/max*90}%;--reviewed:${b.all?b.reviewed/b.all*100:0}%"><div class="bar-dark"></div></div><span class="bar-label">${dayLabel(state.period===7?6-i:29-Math.floor(i*30/7))}</span></div>`).join('');$('#bar-chart').setAttribute('aria-label',`Grafik tujuh kelompok tanggal: ${buckets.map(b=>`${b.all} klaim, ${b.reviewed} ditinjau`).join('; ')}`);const groups=[['Rendah','low','#cce2d2'],['Sedang','medium','#83ae91'],['Tinggi','high','#206b4a']],counts=data.groups;let offset=0;const circumference=2*Math.PI*61;$('#donut-svg').innerHTML=groups.map((g,i)=>{const length=counts[i]/Math.max(1,data.count)*circumference;const html=`<circle cx="80" cy="80" r="61" fill="none" stroke="${g[2]}" stroke-width="13" stroke-dasharray="${Math.max(0,length-5)} ${circumference}" stroke-dashoffset="${-offset}" stroke-linecap="round"/>`;offset+=length;return html;}).join('');$('#risk-percent').textContent=`${Math.round(counts[2]/Math.max(1,data.count)*100)}%`;$('#risk-legend').innerHTML=groups.map((g,i)=>`<div><i class="legend-dot" style="background:${g[2]}"></i>${g[0]}<b>${counts[i]}</b></div>`).join('');}
async function renderTable(){const request=++tableRequest;try{const body=await apiJSON('/api/claims?'+query());if(request!==tableRequest)return;const {total,pages,page:currentPage}=body;state.page=currentPage;const start=(state.page-1)*6,page=body.claims;claims=page;$('#result-count').textContent=total;$('#claim-rows').innerHTML=page.length?page.map(c=>`<tr><td><span class="claim-id">${c.id}</span><span class="claim-diagnosis">${c.icd} · ${c.diagnosis}</span></td><td><div class="hospital"><span class="hospital-icon">${icon('building')}</span><div>${c.facility}<small>${c.city} · Tipe ${c.type}</small></div></div></td><td>${rupiah(c.amount)}</td><td><div class="risk-score ${levels(c)}"><span class="score-bar" aria-hidden="true">${Array.from({length:5},(_,i)=>`<i class="${i<Math.ceil(c.score/20)?'on':''}"></i>`).join('')}</span>${c.score}<span class="sr-only"> dari 99</span></div></td><td>${tag(c)}</td><td><button class="icon-button" data-detail="${c.id}" aria-label="Lihat detail klaim ${c.id}">${icon('arrow')}</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty"><strong>Tidak ada klaim yang cocok.</strong>Coba kata kunci lain atau ubah filter risiko dan status.</td></tr>`;$('#page-info').textContent=total?`Menampilkan ${start+1}–${Math.min(start+6,total)} dari ${total} klaim`:'0 klaim ditemukan';$('#page-number').textContent=`${state.page} / ${pages}`;$('#previous-page').disabled=state.page===1;$('#next-page').disabled=state.page>=pages;$('#sort-risk').setAttribute('aria-label',`Urutkan risiko ${state.descending?'terendah':'tertinggi'} dahulu`);document.querySelector('th:has(#sort-risk)').setAttribute('aria-sort',state.descending?'descending':'ascending');}catch(error){if(request===tableRequest){notify(error.message);$('#claim-rows').innerHTML='<tr><td colspan="6" class="empty">Data belum dapat dimuat. Muat ulang atau coba filter lain.</td></tr>';}}}
const views={history:['Arsip historis','Telusuri klaim sintetis 2019–2025 yang tersimpan di MongoDB.'],overview:['Overview','Satu pandangan untuk setiap klaim yang perlu perhatian Anda.'],claims:['Antrean klaim','Telusuri pengajuan, periksa temuan, dan tentukan prioritas review.'],investigations:['Investigasi risiko','Fokus pada klaim dengan skor risiko 70 atau lebih.'],pipeline:['Pipeline audit','Pahami alur pemeriksaan dari aturan hingga rekomendasi.'],reports:['Laporan','Bawa ringkasan data ke proses review berikutnya.']};
function setView(view){if(!views[view])return;state.view=view;state.status='all';state.risk='all';state.search='';state.page=1;$('#search').value='';$('#risk-filter').value='all';document.querySelectorAll('[data-status]').forEach(b=>{b.classList.toggle('selected',b.dataset.status==='all');b.setAttribute('aria-pressed',b.dataset.status==='all');});const [title,subtitle]=views[view];$('#breadcrumb-current').textContent=title;$('#page-title').innerHTML=`${title}<span class="title-dot">.</span>`;$('#page-subtitle').textContent=subtitle;document.title="SIKEPO";$('#overview-content').hidden=view!=='overview';$('#queue-section').hidden=!['overview','claims','investigations'].includes(view);$('#pipeline-section').hidden=view!=='pipeline';$('#reports-section').hidden=view!=='reports';$('#history-section').hidden=view!=='history';$('#period').hidden=view==='history';$('#export-top').hidden=view==='history';$('#table-title').firstChild.textContent=view==='investigations'?'Klaim dengan sinyal risiko tinggi':view==='claims'?'Seluruh pengajuan klaim':'Klaim yang perlu perhatian';$('#all-claims').hidden=view!=='overview';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');history.replaceState(null,'',`#${view}`);if(view==='history')renderHistory();else renderTable();document.querySelector('main').scrollTo({top:0,behavior:'instant'});}
async function showDetail(id){let c;try{c=await apiJSON('/api/claims/'+encodeURIComponent(id));}catch(error){notify(error.message);return;}const index=claims.findIndex(item=>item.id===id);if(index>=0)claims[index]=c;else claims.push(c);
$('#detail-body').innerHTML=`<h2 id="detail-title">${escapeHTML(c.id)}</h2><div class="detail-meta">${tag(c)}</div><div class="detail-facts"><div><small>Fasilitas kesehatan</small><strong>${escapeHTML(c.facility)}</strong></div><div><small>Diagnosis skenario</small><strong>${escapeHTML(c.icd)} · ${escapeHTML(c.diagnosis)}</strong></div><div><small>Biaya diajukan</small><strong>${rupiah(c.amount)}</strong></div><div><small>Tarif acuan skenario</small><strong>${rupiah(c.tariff)}</strong></div><div><small>Durasi rawat / acuan skenario</small><strong>${c.los} hari / ${c.normalLos} hari</strong></div><div><small>Prioritas aturan + ML</small><strong>${c.score} / 99</strong></div></div><div class="findings">${c.signals.length?c.signals.map(s=>`<div>${icon('scan')}<div><strong>${escapeHTML(s.code)}</strong>${escapeHTML(s.text)}</div></div>`).join(''):`<div>${icon('shield')}<div><strong>Tidak ada indikator terpicu</strong>Review dokumen tetap diperlukan; tidak adanya sinyal bukan bukti kelayakan pembayaran.</div></div>`}<div>${icon('flow')}<div><strong>Isolation Forest</strong>Skor anomali ${c.ml.rawScore.toFixed(4)} · ambang ${c.ml.threshold.toFixed(4)} · ${c.ml.isAnomaly?'terindikasi anomali':'dalam rentang acuan'}. Prioritas aturan ${c.ruleScore}/99. Rekomendasi: ${c.recommendation==='REQUEST_EVIDENCE'?'lengkapi bukti':'siap ditelaah verifikator'}.</div></div><div>${icon('flow')}<div><strong>Jejak pemeriksaan</strong>${escapeHTML(c.assessmentVersion)} · ${c.signals.length} indikator · episode ${escapeHTML(c.episodeId)}.</div></div></div><p class="detail-notice">Sumber: dataset sintetis SiKePO v3. ${c.historical?'Ini salinan arsip historis; keputusan dicatat terpisah dari irisan operasional. ':''}Tidak menggunakan data peserta JKN. Tarif dan durasi adalah nilai skenario. Prioritas bukan probabilitas fraud; status memerlukan review manusia. <a href="/data-methodology.html" target="_blank" rel="noopener">Metodologi data</a></p>`;appendReviewForm(c);$('#claim-dialog').showModal();}
let toastTimeout;function notify(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').hidden=false;toastTimeout=setTimeout(()=>$('#toast').hidden=true,4000);}
function exportCSV(){const link=document.createElement('a');const params=query();if(state.view==='reports'){params.delete('status');params.delete('risk');params.delete('search');params.delete('view');}link.href='/api/claims/export?'+params;link.download='sikepo-claims.csv';document.body.append(link);link.click();link.remove();notify('Ekspor CSV diproses dari database.');}
function appendReviewForm(c){if(typeof sikepoIdentity==='undefined'||!['SA','VK'].includes(sikepoIdentity?.user.role))return;
const form=document.createElement('form');form.className='review-form';form.innerHTML='<h3>Keputusan verifikator</h3><p>Keputusan ini dicatat pada klaim sintetis di workspace.</p><label>Status<select name="status"><option value="HOLD">Minta bukti / tahan</option><option value="APPROVED">Setujui setelah review</option><option value="REJECTED">Tolak dengan alasan</option></select></label><label>Catatan pemeriksaan<textarea name="note" minlength="10" maxlength="1000" required placeholder="Tulis dasar keputusan dan bukti yang ditelaah"></textarea></label><button class="button black" type="submit">Simpan keputusan</button><p role="status"></p>';
form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button'),message=form.querySelector('[role=status]');button.disabled=true;try{await apiJSON('/api/claims/'+encodeURIComponent(c.id)+'/review',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':sikepoIdentity.csrf},body:JSON.stringify({status:form.elements.status.value,note:form.elements.note.value,version:c.reviewVersion})});notify('Keputusan tersimpan di MongoDB.');await showDetail(c.id);renderMetrics();if(state.view==='history')renderHistory();else renderTable();}catch(error){message.textContent=error.message;button.disabled=false;}});
if(c.lastReview){const last=document.createElement('p');last.textContent='Review terakhir: '+c.lastReview.status+' · '+c.lastReview.note;form.prepend(last);}$('#detail-body').append(form);}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
document.querySelectorAll('[data-status]').forEach(b=>b.addEventListener('click',()=>{state.status=b.dataset.status;state.page=1;document.querySelectorAll('[data-status]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',el===b);});renderTable();}));
$('#search').addEventListener('input',e=>{state.search=e.target.value;state.page=1;renderTable();});
$('#risk-filter').addEventListener('change',e=>{state.risk=e.target.value;state.page=1;renderTable();});
$('#period').addEventListener('change',e=>{state.period=Number(e.target.value);state.page=1;renderMetrics();renderTable();});
$('#sort-risk').addEventListener('click',()=>{state.descending=!state.descending;state.page=1;renderTable();});
$('#previous-page').addEventListener('click',()=>{state.page--;renderTable();});$('#next-page').addEventListener('click',()=>{state.page++;renderTable();});
$('#claim-rows').addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b)showDetail(b.dataset.detail);});
$('#all-claims').addEventListener('click',()=>setView('claims'));$('#start-audit').addEventListener('click',()=>{setView('claims');document.querySelector('[data-status="HOLD"]').click();});
$('#export-top').addEventListener('click',exportCSV);$('#export-report').addEventListener('click',exportCSV);
$('#about-button').addEventListener('click',()=>$('#about-dialog').showModal());$('#close-about').addEventListener('click',()=>$('#about-dialog').close());$('#close-detail').addEventListener('click',()=>$('#claim-dialog').close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#notification-button').addEventListener('click',()=>notify(`${summaryCache?.hold??'…'} klaim menunggu review pada periode ini.`));
$('#menu-button').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',$('#sidebar').classList.contains('open'));});
document.addEventListener('click',e=>{if(!e.target.closest('#sidebar, #menu-button')){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNavigation();if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();if(!['overview','claims','investigations'].includes(state.view))setView('claims');$('#search').focus();}});
let historyCursors=[0],historyPosition=0,historyNext=null,historyRequest=0;
async function renderHistory(){const request=++historyRequest,year=$('#history-year').value;try{const data=await apiJSON('/api/history?'+new URLSearchParams({year,after:historyCursors[historyPosition],limit:10}));if(request!==historyRequest)return;historyNext=data.next;$('#history-progress').textContent=`${data.imported.toLocaleString('id-ID')} / ${(data.expected||0).toLocaleString('id-ID')} klaim tahun ${year} ${data.complete?'terverifikasi':'sedang diimpor'}.`;$('#history-rows').innerHTML=data.claims.length?data.claims.map(c=>`<tr><td>${escapeHTML(c.id)}</td><td>${escapeHTML(c.date)}</td><td>${escapeHTML(c.facility)}</td><td>${rupiah(c.amount)}</td><td>${c.score}</td><td>${tag(c)}</td><td><button class="icon-button" data-history-detail="${escapeHTML(c.id)}" aria-label="Lihat detail klaim ${escapeHTML(c.id)}">${icon('arrow')}</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">Belum ada klaim pada halaman ini. Impor mungkin masih berlangsung.</td></tr>';$('#history-prev').disabled=historyPosition===0;$('#history-next').disabled=!historyNext;$('#history-page').textContent=`Halaman ${historyPosition+1}`;}catch(e){notify(e.message);}}
$('#history-year').addEventListener('change',()=>{historyCursors=[0];historyPosition=0;renderHistory();});
$('#history-prev').addEventListener('click',()=>{if(historyPosition){historyPosition--;renderHistory();}});
$('#history-next').addEventListener('click',()=>{if(historyNext){historyPosition++;historyCursors[historyPosition]=historyNext;renderHistory();}});
$('#history-rows').addEventListener('click',e=>{const b=e.target.closest('[data-history-detail]');if(b)showDetail(b.dataset.historyDetail);});
$('#history-find').addEventListener('click',()=>{const id=$('#history-id').value.trim();if(!/^SYN-(2019|202[0-5])-\d{8}$/.test(id)){notify('Masukkan ID arsip lengkap, misalnya SYN-2019-00000004.');return;}showDetail(id);});
async function loadClaims(){setView(location.hash.slice(1)||'overview');await renderMetrics();}
loadClaims();

/* Mobile drawer controls and keyboard containment. */
function closeNavigation(){
 const wasOpen=$('#sidebar').classList.contains('open');
 $('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');
 if(wasOpen)$('#menu-button').focus();
}
$('#close-sidebar')?.addEventListener('click',closeNavigation);
document.addEventListener('keydown',event=>{
 if(!$('#sidebar').classList.contains('open'))return;
 if(event.key==='Escape'){closeNavigation();return;}
 if(event.key!=='Tab')return;
 const items=[...$('#sidebar').querySelectorAll('a[href],button:not([disabled])')].filter(el=>el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');
 const first=items[0],last=items.at(-1);
 if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}
 else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
});
$('#menu-button').addEventListener('click',()=>{if($('#sidebar').classList.contains('open'))$('#close-sidebar')?.focus();});

$('.sidebar-scrim')?.addEventListener('click',closeNavigation);
